mapper.select:
SELECT ,
FROM sys_huagao h
AND h.name LIKE CONCAT('%', #{name}, '%')
AND h.id = #{id}
AND h.shangjiaids = #{shangjiaids}
AND h.status = #{status}
AND h.type LIKE CONCAT('%', #{type}, '%')
AND h.fenlei = #{fenlei}
AND EXISTS ( SELECT 1 FROM sys_huagao_tag ht INNER JOIN sys_tag st ON st.id = ht.tag_id WHERE ht.huagao_id = h.id AND ht.tag_id = #{tagId} AND st.deleted = 0 AND st.tag_type = 'system' )
AND ( h.name LIKE CONCAT('%', #{escapedKeyword}, '%') ESCAPE '\\' OR h.fenlei = #{keyword} OR EXISTS ( SELECT 1 FROM sys_huagao_tag ht INNER JOIN sys_tag st ON st.id = ht.tag_id WHERE ht.huagao_id = h.id AND st.deleted = 0 AND st.tag_type = 'system' AND st.name LIKE CONCAT('%', #{escapedKeyword}, '%') ESCAPE '\\' ) OR EXISTS ( SELECT 1 FROM sys_huagao_tag ht INNER JOIN sys_tag st ON st.id = ht.tag_id WHERE ht.huagao_id = h.id AND st.deleted = 0 AND st.tag_type = 'free' AND st.name LIKE CONCAT('%', #{escapedKeyword}, '%') ESCAPE '\\' ) OR EXISTS ( SELECT 1 FROM sys_huagao_tag ht INNER JOIN sys_tag_alias sta ON sta.tag_id = ht.tag_id INNER JOIN sys_tag st ON st.id = sta.tag_id WHERE ht.huagao_id = h.id AND st.deleted = 0 AND sta.alias_name LIKE CONCAT('%', #{escapedKeyword}, '%') ESCAPE '\\' )
OR EXISTS ( SELECT 1 FROM sys_huagao_tag ht INNER JOIN sys_tag st ON st.id = ht.tag_id WHERE ht.huagao_id = h.id AND st.deleted = 0 AND st.normalized_name LIKE CONCAT('%', #{escapedNormalizedKeyword}, '%') ESCAPE '\\' ) OR EXISTS ( SELECT 1 FROM sys_huagao_tag ht INNER JOIN sys_tag_alias sta ON sta.tag_id = ht.tag_id INNER JOIN sys_tag st ON st.id = sta.tag_id WHERE ht.huagao_id = h.id AND st.deleted = 0 AND sta.normalized_name LIKE CONCAT('%', #{escapedNormalizedKeyword}, '%') ESCAPE '\\' )
)
ORDER BY search_score DESC, h.id DESC
ORDER BY h.id DESC
